	assert(mark <= buffer->_limit || buffer->_vfixed);
	buffer->_position = mark;
}

INLINE uint8_t /* <=== sldns_buffer_read_u8_at */ 
sldns_buffer_read_u8_at(sldns_buffer *buffer, size_t at)
